"""SCRIPTED rejection contracts; no actual observations generated by this test."""
import pytest
from scripts.figures.native_authoring_ir_qa_v14 import render
from scripts.analyze_native_authoring_ir_qa_v14 import SCHEMA,ACTUAL,FIXTURE


def test_rejects_scripted_evidence_in_actual_figure(tmp_path):
    with pytest.raises(ValueError,match='actual QA'):
        render({'schema':SCHEMA,'classification':FIXTURE},tmp_path/'fixture')


def test_rejects_unbound_actual_label(tmp_path):
    with pytest.raises(ValueError,match='hash'):
        render({'schema':SCHEMA,'classification':ACTUAL,'content_sha256':'forged'},tmp_path/'fixture')
